class Solution {
  // starts[i] is true when pat occurs at index i (an empty pattern occurs everywhere, including n)
  private static boolean[] occurrences(String s, String pat) {
    int n = s.length(), m = pat.length();
    boolean[] starts = new boolean[n + 2];
    if (m == 0) {
      java.util.Arrays.fill(starts, 0, n + 1, true);
      return starts;
    }
    int[] fail = new int[m];
    for (int i = 1, k = 0; i < m; i++) {
      while (k > 0 && pat.charAt(i) != pat.charAt(k)) k = fail[k - 1];
      if (pat.charAt(i) == pat.charAt(k)) k++;
      fail[i] = k;
    }
    for (int i = 0, k = 0; i < n; i++) {
      while (k > 0 && (k == m || s.charAt(i) != pat.charAt(k))) k = fail[k - 1];
      if (s.charAt(i) == pat.charAt(k)) k++;
      if (k == m) starts[i - m + 1] = true;
    }
    return starts;
  }

  private static int[] nextOccurrence(boolean[] starts, int n) {
    int INF = Integer.MAX_VALUE / 2;
    int[] next = new int[n + 3];
    next[n + 2] = next[n + 1] = INF;
    for (int i = n; i >= 0; i--) next[i] = starts[i] ? i : next[i + 1];
    return next;
  }

  public int shortestMatchingSubstring(String s, String p) {
    int n = s.length();
    int a = p.indexOf('*'), b = p.lastIndexOf('*');
    String A = p.substring(0, a), B = p.substring(a + 1, b), C = p.substring(b + 1);
    boolean[] matchA = occurrences(s, A);
    int[] nextB = nextOccurrence(occurrences(s, B), n),
        nextC = nextOccurrence(occurrences(s, C), n);
    int INF = Integer.MAX_VALUE / 2, best = INF;
    for (int i = 0; i <= n; i++) {
      if (!matchA[i]) continue;
      int from = i + A.length();
      if (from > n) continue;
      int j = nextB[from];
      if (j >= INF) continue;
      int fromC = j + B.length();
      if (fromC > n) continue;
      int k = nextC[fromC];
      if (k >= INF) continue;
      best = Math.min(best, k + C.length() - i);
    }
    return best >= INF ? -1 : best;
  }
}
